import{_ as o,a as s,c as t,ac as a}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第74–80课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第74–80课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第67–73课","link":"/life/english/new-concept/book-1/review-part-10"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第81–87课","link":"/life/english/new-concept/book-1/review-part-12"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第67–73课","link":"/life/english/new-concept/book-1/review-part-10"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第81–87课","link":"/life/english/new-concept/book-1/review-part-12"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-11.md","filePath":"life/english/new-concept/book-1/review-part-11.md"}'),n={name:"life/english/new-concept/book-1/review-part-11.md"};function r(i,e,l,h,d,u){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第74–80课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第74–80课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第74–80课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第74–80课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-74-·-不规则过去式" tabindex="-1">Lesson 74 · 不规则过去式 <a class="header-anchor" href="#lesson-74-·-不规则过去式" aria-label="Permalink to &quot;Lesson 74 · 不规则过去式 {#lesson-74-·-不规则过去式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Did the guard show you the right road?</p><h3 id="练习-1-73" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-73" aria-label="Permalink to &quot;练习 1 {#练习-1-73}&quot;">​</a></h3><p>填原形：Did the guard ___ (show) you the road?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> show</p><p><strong>解析：</strong> 按本课规则判断：部分高频动词的过去式不是加 ed：go→went、see→saw、say→said、take→took。肯定句使用过去式，问句和否定句中 did 后恢复原形。复述路线可以按先后顺序组织动作，但 next、then 等顺序词不自动决定时态；应先确认整个故事发生在过去。人名变化不会改变过去式形式。</p></details><p><strong>表达迁移：</strong> 围绕“叙述问路和找到目的地的过程”写两至三句，再读给同伴听。至少使用一次不规则过去式，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Did the guard show you the right road? We took the wrong bus and went to the harbour.</p><p>Did 前置询问过去事件，show 恢复原形；you 是接受者，the right road 是被指出的信息。 Took 与 went 是并列的过去时谓语，分别来自 take 和 go；and 连接两个先后相关的动作。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-074">回看本课</a></p><h2 id="lesson-75-·-过去时间标记与-buy-bought" tabindex="-1">Lesson 75 · 过去时间标记与 buy/bought <a class="header-anchor" href="#lesson-75-·-过去时间标记与-buy-bought" aria-label="Permalink to &quot;Lesson 75 · 过去时间标记与 buy/bought {#lesson-75-·-过去时间标记与-buy-bought}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I bought these boots three weeks ago.</p><h3 id="练习-1-74" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-74" aria-label="Permalink to &quot;练习 1 {#练习-1-74}&quot;">​</a></h3><p>填过去式：I ___ (buy) these boots last month.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> bought</p><p><strong>解析：</strong> 按本课规则判断：明确结束的过去时间如 last month、two days ago，通常与一般过去时配合。buy 的过去式为 bought，wear 的过去式为 wore。ago 表从现在向前推多少时间，放在数量短语之后。询问过去购买用 Did you buy ...?，不能在 did 后保留 bought。大小合适与舒适是不同属性，描述时可分别说明。</p></details><p><strong>表达迁移：</strong> 围绕“比较过去购买与现在需要”写两至三句，再读给同伴听。至少使用一次过去时间标记与 buy/bought，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I bought these boots three weeks ago. Did you wear the new shoes yesterday?</p><p>Bought 是 buy 的不规则过去式；these boots 为宾语，three weeks ago 表从现在回溯三周。 Did 承担过去标记，wear 不用过去式 wore；the new shoes 为宾语，yesterday 指过去一天。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-075">回看本课</a></p><h2 id="lesson-76-·-过去时间标记与-buy-bought" tabindex="-1">Lesson 76 · 过去时间标记与 buy/bought <a class="header-anchor" href="#lesson-76-·-过去时间标记与-buy-bought" aria-label="Permalink to &quot;Lesson 76 · 过去时间标记与 buy/bought {#lesson-76-·-过去时间标记与-buy-bought}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Did you wear the new shoes yesterday?</p><h3 id="练习-1-75" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-75" aria-label="Permalink to &quot;练习 1 {#练习-1-75}&quot;">​</a></h3><p>填原形：Did you ___ (wear) them?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> wear</p><p><strong>解析：</strong> 按本课规则判断：明确结束的过去时间如 last month、two days ago，通常与一般过去时配合。buy 的过去式为 bought，wear 的过去式为 wore。ago 表从现在向前推多少时间，放在数量短语之后。询问过去购买用 Did you buy ...?，不能在 did 后保留 bought。大小合适与舒适是不同属性，描述时可分别说明。</p></details><p><strong>表达迁移：</strong> 围绕“比较过去购买与现在需要”写两至三句，再读给同伴听。至少使用一次过去时间标记与 buy/bought，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Did you wear the new shoes yesterday? I bought these boots three weeks ago.</p><p>Did 承担过去标记，wear 不用过去式 wore；the new shoes 为宾语，yesterday 指过去一天。 Bought 是 buy 的不规则过去式；these boots 为宾语，three weeks ago 表从现在回溯三周。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-076">回看本课</a></p><h2 id="lesson-77-·-时间介词与否定疑问句" tabindex="-1">Lesson 77 · 时间介词与否定疑问句 <a class="header-anchor" href="#lesson-77-·-时间介词与否定疑问句" aria-label="Permalink to &quot;Lesson 77 · 时间介词与否定疑问句 {#lesson-77-·-时间介词与否定疑问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My appointment is at ten on Thursday.</p><h3 id="练习-1-76" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-76" aria-label="Permalink to &quot;练习 1 {#练习-1-76}&quot;">​</a></h3><p>补介词：___ ten o&#39;clock.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> at</p><p><strong>解析：</strong> 按本课规则判断：预约时 at + 钟点，on + 某日，in + 月份或年份。否定疑问句如 Can&#39;t you come earlier? 常带有期待或惊讶，不是完全中性的询问。回答 Yes, I can 表能，No, I can&#39;t 表不能，按实际情况回答，不按中文句首“是/不是”机械翻译。本页训练预约表达，不提供牙科处理建议。</p></details><p><strong>表达迁移：</strong> 围绕“预约服务并说明可用时间”写两至三句，再读给同伴听。至少使用一次时间介词与否定疑问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My appointment is at ten on Thursday. Can you come earlier on Friday?</p><p>My appointment 是主语，is 连接时间表语；at ten 表钟点，on Thursday 表某一天。 Can you 询问是否能够；come 用原形，earlier 是副词比较级，on Friday 交代是哪天。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-077">回看本课</a></p><h2 id="lesson-78-·-时间介词与否定疑问句" tabindex="-1">Lesson 78 · 时间介词与否定疑问句 <a class="header-anchor" href="#lesson-78-·-时间介词与否定疑问句" aria-label="Permalink to &quot;Lesson 78 · 时间介词与否定疑问句 {#lesson-78-·-时间介词与否定疑问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Can you come earlier on Friday?</p><h3 id="练习-1-77" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-77" aria-label="Permalink to &quot;练习 1 {#练习-1-77}&quot;">​</a></h3><p>补介词：___ Thursday morning.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> on</p><p><strong>解析：</strong> 按本课规则判断：预约时 at + 钟点，on + 某日，in + 月份或年份。否定疑问句如 Can&#39;t you come earlier? 常带有期待或惊讶，不是完全中性的询问。回答 Yes, I can 表能，No, I can&#39;t 表不能，按实际情况回答，不按中文句首“是/不是”机械翻译。本页训练预约表达，不提供牙科处理建议。</p></details><p><strong>表达迁移：</strong> 围绕“预约服务并说明可用时间”写两至三句，再读给同伴听。至少使用一次时间介词与否定疑问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Can you come earlier on Friday? My appointment is at ten on Thursday.</p><p>Can you 询问是否能够；come 用原形，earlier 是副词比较级，on Friday 交代是哪天。 My appointment 是主语，is 连接时间表语；at ten 表钟点，on Thursday 表某一天。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-078">回看本课</a></p><h2 id="lesson-79-·-need-与-must" tabindex="-1">Lesson 79 · need 与 must <a class="header-anchor" href="#lesson-79-·-need-与-must" aria-label="Permalink to &quot;Lesson 79 · need 与 must {#lesson-79-·-need-与-must}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We need to buy rice and tomatoes.</p><h3 id="练习-1-78" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-78" aria-label="Permalink to &quot;练习 1 {#练习-1-78}&quot;">​</a></h3><p>填小词：We need ___ buy rice.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> 按本课规则判断：need 作实义动词时，可接名词或 to do：need some rice、need to buy rice。第三人称用 needs，否定借助 don&#39;t/doesn&#39;t。must 是情态动词，直接加原形，不加 to。needn&#39;t 是“不必”，其后直接接动词原形。学习时先确定用的是实义动词 need 还是情态表达，避免混用句式。</p></details><p><strong>表达迁移：</strong> 围绕“根据购物清单表达需要去哪里”写两至三句，再读给同伴听。至少使用一次need 与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We need to buy rice and tomatoes. She must go to the pharmacy before six.</p><p>Need 后接不定式 to buy；rice 不可数，tomatoes 是复数可数名词，两者都作 buy 的宾语。 She 为主语，must 后直接接 go；to the pharmacy 表目的地，before six 表时间界限。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-079">回看本课</a></p><h2 id="lesson-80-·-need-与-must" tabindex="-1">Lesson 80 · need 与 must <a class="header-anchor" href="#lesson-80-·-need-与-must" aria-label="Permalink to &quot;Lesson 80 · need 与 must {#lesson-80-·-need-与-must}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She must go to the pharmacy before six.</p><h3 id="练习-1-79" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-79" aria-label="Permalink to &quot;练习 1 {#练习-1-79}&quot;">​</a></h3><p>删去多余词：She must to go now.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She must go now.</p><p><strong>解析：</strong> 按本课规则判断：need 作实义动词时，可接名词或 to do：need some rice、need to buy rice。第三人称用 needs，否定借助 don&#39;t/doesn&#39;t。must 是情态动词，直接加原形，不加 to。needn&#39;t 是“不必”，其后直接接动词原形。学习时先确定用的是实义动词 need 还是情态表达，避免混用句式。</p></details><p><strong>表达迁移：</strong> 围绕“根据购物清单表达需要去哪里”写两至三句，再读给同伴听。至少使用一次need 与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She must go to the pharmacy before six. We need to buy rice and tomatoes.</p><p>She 为主语，must 后直接接 go；to the pharmacy 表目的地，before six 表时间界限。 Need 后接不定式 to buy；rice 不可数，tomatoes 是复数可数名词，两者都作 buy 的宾语。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-080">回看本课</a></p>',60)])])}const m=o(n,[["render",r]]);export{c as __pageData,m as default};
